package com.cyberpath.learning;

import android.app.*;
import android.content.*;
import android.os.Build;
import android.util.AtomicFile;
import org.json.*;
import java.io.*;
import java.nio.charset.StandardCharsets;
import java.time.*;
import java.time.temporal.*;
import java.util.*;

/** Profile-bound, revision-checked reminder transactions. Never touches Study records. */
public final class ReminderActions extends BroadcastReceiver {
 public static final String ACTION="com.cyberpath.learning.REMINDER_ACTION";
 public static String identity(JSONObject row){return row.optString("updatedAt")+"|"+row.optInt("editRevision")+"|"+row.optString("status");}
 public static PendingIntent pending(Context c,String profile,JSONObject row,String operation){
  if(AppLock.enabled(c))return PendingIntent.getActivity(c,704,new Intent(c,MainActivity.class).putExtra("lwRoute","reminders"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
  Intent i=new Intent(c,ReminderActions.class).setAction(ACTION).setData(android.net.Uri.parse("lw-reminder://action/"+profile+"/"+row.optString("id")+"/"+operation+"/"+Integer.toHexString(identity(row).hashCode())))
   .putExtra("profile",profile).putExtra("id",row.optString("id")).putExtra("operation",operation).putExtra("identity",identity(row));
  return PendingIntent.getBroadcast(c,0,i,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);
 }
 public static Notification.Action button(Context c,String profile,JSONObject row,String operation,String label){
  Notification.Action.Builder b=new Notification.Action.Builder(null,label,pending(c,profile,row,operation));
  if(Build.VERSION.SDK_INT>=31)b.setAuthenticationRequired(true);return b.build();
 }
 private static JSONObject find(JSONArray rows,String id){for(int i=0;i<rows.length();i++){JSONObject r=rows.optJSONObject(i);if(r!=null&&id.equals(r.optString("id")))return r;}return null;}
 private static int weekday(LocalDate day){return day.getDayOfWeek().getValue()%7;}
 private static boolean includes(JSONArray values,int n){if(values==null)return false;for(int i=0;i<values.length();i++)if(values.optInt(i,-1)==n)return true;return false;}
 private static LocalDate custom(JSONObject r,JSONObject rule,LocalDate after)throws Exception{
  boolean completion=rule.optBoolean("afterCompletion");LocalDate base=completion?after:LocalDate.parse(r.getString("date")),limit=base.isAfter(after)?base:after;
  int interval=Math.max(1,rule.optInt("interval",1));String unit="custom".equals(r.optString("repeat"))?rule.optString("unit","day"):unit(r.optString("repeat"));JSONArray days=rule.optJSONArray("weekdays");
  if("day".equals(unit))return base.plusDays((ChronoUnit.DAYS.between(base,limit)/interval+1)*interval);
  if("week".equals(unit)){LocalDate anchor=base.with(TemporalAdjusters.previousOrSame(DayOfWeek.MONDAY));for(int n=1;n<=interval*7+7;n++){LocalDate d=limit.plusDays(n);long week=ChronoUnit.DAYS.between(anchor,d)/7;if(week%interval==0&&(days==null||days.length()==0?weekday(d)==weekday(base):includes(days,weekday(d))))return d;}}
  if("month".equals(unit)){long elapsed=ChronoUnit.MONTHS.between(YearMonth.from(base),YearMonth.from(limit)),start=elapsed/interval*interval;for(long n=start;n<=start+interval*2L;n+=interval){YearMonth m=YearMonth.from(base).plusMonths(n);String ordinal=rule.optString("ordinal");LocalDate d;if(!ordinal.isEmpty()){int day=days.getInt(0);DayOfWeek dw=DayOfWeek.of(day==0?7:day);d="last".equals(ordinal)?m.atEndOfMonth().with(TemporalAdjusters.previousOrSame(dw)):m.atDay(1).with(TemporalAdjusters.nextOrSame(dw)).plusWeeks(Integer.parseInt(ordinal)-1);}else d=m.atDay(Math.min(completion?base.getDayOfMonth():r.optInt("anchorDay",base.getDayOfMonth()),m.lengthOfMonth()));if(d.isAfter(limit))return d;}}
  if("year".equals(unit)){int elapsed=limit.getYear()-base.getYear(),start=elapsed/interval*interval;for(int n=start;n<=start+interval;n+=interval){YearMonth m=YearMonth.of(base.getYear()+n,completion?base.getMonthValue():r.optInt("anchorMonth",base.getMonthValue()));LocalDate d=m.atDay(Math.min(completion?base.getDayOfMonth():r.optInt("anchorDay",base.getDayOfMonth()),m.lengthOfMonth()));if(d.isAfter(limit))return d;}}
  throw new IllegalArgumentException("The repeat date is outside the supported calendar.");
 }
 private static String unit(String repeat){return "weekly".equals(repeat)?"week":"monthly".equals(repeat)?"month":"yearly".equals(repeat)?"year":"day";}
 private static LocalDate nextBase(JSONObject r,LocalDate after)throws Exception{
  if("none".equals(r.optString("repeat","none")))return null;JSONObject rule=r.optJSONObject("rule");if(rule==null)rule=new JSONObject();int count=rule.optInt("count");if(count>0&&r.optInt("occurrence",1)>=count)return null;
  // All simple schedules are the interval-one specialization of the same rule.
  LocalDate result=custom(r,rule,after);if(result.getYear()<1900||result.getYear()>9999)throw new IllegalArgumentException("The repeat date is outside the supported calendar.");String end=rule.optString("endDate");return !end.isEmpty()&&result.isAfter(LocalDate.parse(end))?null:result;
 }
 public static String nextDay(JSONObject r,Instant now)throws Exception{
  JSONObject extra=r.optJSONObject("extra");String zone=extra==null?"local":extra.optString("timeZone","local");LocalDate after=now.atZone("local".equals(zone)?ZoneId.systemDefault():ZoneId.of(zone)).toLocalDate();LocalDate d=nextBase(r,after);
  for(int n=0;d!=null;n++){if(n>3660)throw new IllegalArgumentException("No matching working date was found.");boolean allowed=extra==null||(!extra.has("workdays")||includes(extra.optJSONArray("workdays"),weekday(d)));JSONArray holidays=extra==null?null:extra.optJSONArray("holidays");if(holidays!=null)for(int j=0;j<holidays.length();j++)if(d.toString().equals(holidays.optString(j)))allowed=false;if(allowed)return d.toString();d=nextBase(r,d);}return "";
 }
 public static JSONObject apply(JSONObject w,String id,String operation,String expected,Instant now)throws Exception{
  JSONArray rows=w.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items");JSONObject r=find(rows,id);if(r==null||!identity(r).equals(expected))throw new IllegalStateException("This reminder changed. Open Reminders for the latest version.");String at=now.toString();JSONObject before=new JSONObject(r.toString());String generated="";
  if("done".equals(operation)){if(!"pending".equals(r.optString("status")))throw new IllegalStateException("Already finished.");String date=nextDay(r,now);if(!date.isEmpty()){if(rows.length()>=10000||r.optInt("occurrence",1)>=10000)throw new IllegalStateException("The reminder collection or repeat history is full.");JSONObject next=new JSONObject(r.toString());generated="reminder-"+UUID.randomUUID().toString().replace("-","");String alert=r.optString("alertDate");if(!alert.isEmpty())next.put("alertDate",LocalDate.parse(date).plusDays(ChronoUnit.DAYS.between(LocalDate.parse(r.getString("date")),LocalDate.parse(alert))).toString());next.put("id",generated).put("date",date).put("snoozedUntil","").put("occurrence",r.optInt("occurrence",1)+1).put("status","pending").put("completedAt","").put("createdAt",at).put("updatedAt",at).put("nextId","").put("parentId",id).put("editRevision",0);rows.put(next);}r.put("status","completed").put("completedAt",at).put("nextId",generated).put("updatedAt",at);}
  else if("snooze".equals(operation)){if(!"pending".equals(r.optString("status"))||!r.optBoolean("notify")||r.optString("time").isEmpty())throw new IllegalStateException("An unfinished phone alert is required.");r.put("snoozedUntil",java.time.format.DateTimeFormatter.ofPattern("uuuu-MM-dd'T'HH:mm:ss.SSS'Z'").withZone(ZoneOffset.UTC).format(now.plusSeconds(600))).put("editRevision",r.optInt("editRevision")+1).put("updatedAt",at);}
  else if("tomorrow".equals(operation)){if(!"pending".equals(r.optString("status"))||r.optString("date").isEmpty())throw new IllegalStateException("An unfinished dated reminder is required.");LocalDate old=LocalDate.parse(r.getString("date")),date=LocalDate.now().plusDays(1);if(!date.isAfter(old))date=old.plusDays(1);String alert=r.optString("alertDate");if(!alert.isEmpty())r.put("alertDate",LocalDate.parse(alert).plusDays(ChronoUnit.DAYS.between(old,date)).toString());r.put("date",date.toString()).put("anchorDay",date.getDayOfMonth()).put("anchorMonth",date.getMonthValue()).put("snoozedUntil","").put("editRevision",r.optInt("editRevision")+1).put("updatedAt",at);}
  else throw new IllegalArgumentException("Unknown reminder action.");
  return new JSONObject().put("id",id).put("before",before).put("after",identity(r)).put("generated",generated).put("at",at);
 }
 public static void undo(JSONObject w,JSONObject receipt)throws Exception{
  JSONArray rows=w.getJSONObject("learning").getJSONObject("organizer").getJSONArray("items");String id=receipt.getString("id"),generated=receipt.optString("generated");JSONObject row=find(rows,id);if(row==null||!receipt.getString("after").equals(identity(row)))throw new IllegalStateException("This reminder changed. Keep its latest changes.");if(!generated.isEmpty()){JSONObject next=find(rows,generated);if(next==null||!"pending".equals(next.optString("status"))||next.optInt("editRevision")!=0||!next.optString("nextId").isEmpty()||!receipt.getString("at").equals(next.optString("updatedAt")))throw new IllegalStateException("The next occurrence changed. Keep its history.");}
  for(int i=rows.length()-1;i>=0;i--){String key=rows.getJSONObject(i).optString("id");if(key.equals(generated))rows.remove(i);else if(key.equals(id))rows.put(i,receipt.getJSONObject("before"));}
 }
 private static void save(Context c,JSONObject w)throws Exception{long revision=w.optLong("revision");w.put("nativeReminderRevision",revision+1).put("revision",revision+1).put("updatedAt",Instant.now().toString());AtomicFile file=new AtomicFile(new File(ProfileFiles.root(c),"studio-workspace.json"));FileOutputStream stream=null;try{byte[] bytes=w.toString().getBytes(StandardCharsets.UTF_8);if(bytes.length>25000000)throw new IOException("The workspace is full.");stream=file.startWrite();stream.write(bytes);file.finishWrite(stream);}catch(Exception e){if(stream!=null)file.failWrite(stream);throw e;}PersonalReminders.sync(c,w);NativeServices.onWorkspaceSaved(c);}
 public static boolean transact(Context c,Intent intent)throws Exception{synchronized(AppFiles.LOCK){String profile=intent.getStringExtra("profile");ProfileFiles.requireActive(c,profile);if(AppLock.enabled(c))throw new IllegalStateException("Open LW and unlock before changing a reminder.");JSONObject w=AppFiles.workspace(c);String operation=intent.getStringExtra("operation");JSONObject receipt;if("undo".equals(operation)){receipt=new JSONObject(NativeServices.prefs(c).getString("reminderUndo","{}"));if(!intent.getStringExtra("identity").equals(receipt.optString("after")))return false;undo(w,receipt);save(c,w);NativeServices.prefs(c).edit().remove("reminderUndo").apply();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).cancel("reminder-undo",913);return true;}receipt=apply(w,intent.getStringExtra("id"),operation,intent.getStringExtra("identity"),Instant.now());save(c,w);NativeServices.prefs(c).edit().putString("reminderUndo",receipt.toString()).apply();showUndo(c,profile,receipt);return true;}}
 private static void showUndo(Context c,String profile,JSONObject receipt)throws Exception{PersonalReminders.channel(c);if(!PersonalReminders.allowed(c))return;JSONObject row=new JSONObject().put("id",receipt.getString("id")).put("updatedAt",receipt.getJSONObject("before").optString("updatedAt"));Intent undo=new Intent(c,ReminderActions.class).setAction(ACTION).setData(android.net.Uri.parse("lw-reminder://undo/"+profile+"/"+receipt.getString("id"))).putExtra("profile",profile).putExtra("operation","undo").putExtra("identity",receipt.getString("after"));PendingIntent action=PendingIntent.getBroadcast(c,0,undo,PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE);Notification n=new Notification.Builder(c,PersonalReminders.CHANNEL).setSmallIcon(R.drawable.notification_leaf).setContentTitle(UiText.of(c,"Reminder updated","रिमाइंडर बदला गया")).setContentText(receipt.getJSONObject("before").optString("title")).setContentIntent(PendingIntent.getActivity(c,705,new Intent(c,MainActivity.class).putExtra("lwRoute","reminders"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).addAction(new Notification.Action.Builder(null,UiText.of(c,"Undo","वापस लें"),action).build()).setLocalOnly(!NativeServices.prefs(c).getBoolean("watchMirror",true)).setVisibility(Notification.VISIBILITY_PRIVATE).setTimeoutAfter(600000).build();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify("reminder-undo",913,n);}
 @Override public void onReceive(Context c,Intent i){if(!ACTION.equals(i.getAction()))return;PendingResult result=goAsync();NativeServices.IO.execute(()->{try{transact(c,i);}catch(Exception e){NativeServices.prefs(c).edit().putString("reminderActionError",e.getMessage()).apply();try{PersonalReminders.channel(c);if(PersonalReminders.allowed(c)){Notification n=new Notification.Builder(c,PersonalReminders.CHANNEL).setSmallIcon(R.drawable.notification_leaf).setContentTitle(UiText.of(c,"Reminder unchanged","रिमाइंडर नहीं बदला")).setContentText(e.getMessage()).setContentIntent(PendingIntent.getActivity(c,706,new Intent(c,MainActivity.class).putExtra("lwRoute","reminders"),PendingIntent.FLAG_UPDATE_CURRENT|PendingIntent.FLAG_IMMUTABLE)).setVisibility(Notification.VISIBILITY_PRIVATE).setAutoCancel(true).build();((NotificationManager)c.getSystemService(Context.NOTIFICATION_SERVICE)).notify("reminder-undo",913,n);}}catch(Exception ignored){}}finally{LearningWidget.updateAll(c);PersonalReminderWidget.updateAll(c);result.finish();}});}
}
